/* Import ALL Windows 98 styles from web kernel */

/* Map Docusaurus Infima variables to web kernel variables */
:root {
  /* Fonts */
  --ifm-font-family-base: 'MS Sans Serif', 'Microsoft Sans Serif', Arial, sans-serif;
  --ifm-font-family-monospace: 'Courier New', Courier, monospace;
  --ifm-font-size-base: 11px;
  
  /* Colors - Windows 98 palette from web kernel */
  --ifm-color-primary: var(--color-highlight);
  --ifm-color-primary-dark: var(--color-highlight);
  --ifm-color-primary-darker: var(--color-highlight);
  --ifm-color-primary-darkest: var(--color-highlight);
  --ifm-color-primary-light: var(--color-highlight);
  --ifm-color-primary-lighter: var(--color-highlight);
  --ifm-color-primary-lightest: var(--color-highlight);
  
  /* Background colors */
  --ifm-background-color: var(--color-button-face);
  --ifm-background-surface-color: var(--color-button-face);
  
  /* Text colors */
  --ifm-color-content: var(--color-window-text);
  --ifm-heading-color: var(--color-window-text);
  
  /* Navbar */
  --ifm-navbar-background-color: var(--color-button-face);
  --ifm-navbar-height: 28px;
  
  /* Sidebar */
  --ifm-sidebar-width: 250px;
  
  /* Code */
  --ifm-code-font-size: 11px;
  --docusaurus-highlighted-code-line-bg: rgba(0, 0, 0, 0.1);
}

/* Dark theme mapping */
[data-theme='dark'] {
  --ifm-background-color: var(--color-window-text);
  --ifm-background-surface-color: var(--color-window-text);
  --ifm-color-content: var(--color-window-text);
  --ifm-heading-color: var(--color-window-text);
  --ifm-navbar-background-color: var(--color-window-text);
}

/* Windows 98 Help System Structure */
.help-layout {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: var(--ifm-background-color);
  font-family: 'MS Sans Serif', 'Microsoft Sans Serif', Arial, sans-serif;
  font-family: var(--ifm-font-family-base);
}

.help-menu-bar {
  height: 22px;
  background: #c0c0c0;
  border-bottom: 1px solid #808080;
  display: flex;
  align-items: center;
  padding: 0 4px;
  font-size: 11px;
}

.help-menu-item {
  padding: 2px 8px;
  cursor: pointer;
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
}

.help-menu-item:hover {
  background: #000080;
  color: #ffffff;
}

.help-toolbar {
  height: 28px;
  background: #c0c0c0;
  border-bottom: 1px solid #808080;
  display: flex;
  align-items: center;
  padding: 2px 4px;
  gap: 2px;
}

.help-toolbar-button {
  width: 24px;
  height: 24px;
  background: #c0c0c0;
  border-top: 2px solid #ffffff;
  border-left: 2px solid #ffffff;
  border-right: 2px solid #808080;
  border-bottom: 2px solid #808080;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.help-toolbar-button:active {
  border-top: 2px solid #808080;
  border-left: 2px solid #808080;
  border-right: 2px solid #ffffff;
  border-bottom: 2px solid #ffffff;
}

.help-toolbar-separator {
  width: 2px;
  height: 20px;
  background: #808080;
  margin: 0 4px;
}

.help-tab-bar {
  height: 24px;
  background: #c0c0c0;
  border-bottom: 1px solid #808080;
  display: flex;
}

.help-tab {
  padding: 2px 12px;
  font-size: 11px;
  background: #c0c0c0;
  border-top: 2px solid #ffffff;
  border-left: 2px solid #ffffff;
  border-right: 2px solid #808080;
  border-bottom: none;
  cursor: pointer;
  margin-right: 2px;
}

.help-tab.active {
  border-top: 2px solid #808080;
  border-left: 2px solid #808080;
  border-right: 2px solid #ffffff;
  border-bottom: 1px solid #c0c0c0;
  margin-bottom: -1px;
}

.help-main-content {
  flex: 1;
  display: flex;
  min-height: 0;
  overflow: hidden;
}

.help-status-bar {
  height: 22px;
  background: var(--color-button-face);
  border-top: 1px solid var(--color-button-shadow);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 4px;
  font-size: 11px;
}

/* Apply Windows 98 styling to Docusaurus elements */
.navbar {
  background: var(--color-button-face) !important;
  border-bottom: 1px solid var(--color-button-shadow);
  box-shadow: none;
  height: 28px;
  padding: 0 8px;
}

.navbar__link {
  color: var(--color-window-text);
  font-size: 11px;
  font-family: 'MS Sans Serif', 'Microsoft Sans Serif', Arial, sans-serif;
  font-family: var(--ifm-font-family-base);
  padding: 4px 8px;
}

.navbar__link:hover {
  background: var(--color-highlight);
