  color: var(--color-window-text);
  border: 2px solid;
  border-color: var(--color-button-highlight) var(--color-button-shadow) var(--color-button-shadow) var(--color-button-highlight);
  border-radius: 0;
  padding: 4px 12px;
  font-family: 'MS Sans Serif', 'Microsoft Sans Serif', Arial, sans-serif;
  font-family: var(--ifm-font-family-base);
  font-size: 11px;
  cursor: pointer;
}

.button:hover {
  background: var(--color-button-highlight);
}

.button:active {
  border-color: var(--color-button-shadow) var(--color-button-highlight) var(--color-button-highlight) var(--color-button-shadow);
}

::-webkit-scrollbar {
  width: 16px;
  height: 16px;
}

::-webkit-scrollbar-track {
  background: var(--color-button-face);
  border: 1px solid;
  border-color: var(--color-button-shadow) var(--color-button-highlight) var(--color-button-highlight) var(--color-button-shadow);
}

::-webkit-scrollbar-thumb {
  background: var(--color-button-face);
  border: 2px solid;
  border-color: var(--color-button-highlight) var(--color-button-shadow) var(--color-button-shadow) var(--color-button-highlight);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--color-button-highlight);
}

::-webkit-scrollbar-corner {
  background: var(--color-button-face);
